//! The states' commemorative days, code by code.
//!
//! Each anchor is a day a state's code designates for observance, in the
//! first year the table carries it and in 2026, with the date its rule
//! gives; the dates were worked out from the codes' rules by a script apart
//! from this crate (Python's `datetime`), not taken from its output.

use hc_calendar::Rd;
use hc_calendars_solar::gregorian;
use hc_holiday::countries::UNITED_STATES;
use hc_holiday::engine::{Holiday, HolidayCalendar};
use hc_holiday::rule::{Confidence, Kind};

fn ymd(year: i64, month: u8, day: u8) -> Rd {
    match gregorian::to_fixed(year, month, day) {
        Ok(fixed) => fixed,
        Err(error) => panic!("{year}-{month:02}-{day:02} is not a date: {error:?}"),
    }
}

fn named(region: &str, name: &str, year: i64) -> Vec<Holiday> {
    HolidayCalendar::for_year(&UNITED_STATES, Some(region), year)
        .in_year(year)
        .into_iter()
        .filter(|holiday| holiday.name == name && !holiday.regions.is_empty())
        .collect()
}

