#[test]
fn every_commemorative_day_falls_where_its_code_puts_it() {
    for &(region, name, year, month, day, confidence) in ANCHORS {
        let found = named(region, name, year);
        assert_eq!(found.len(), 1, "{region} {name} {year}: {found:?}");
        assert_eq!(
            found[0].date,
            ymd(year, month, day),
            "{region} {name} {year}"
        );
        assert_eq!(found[0].kind, Kind::Observance, "{region} {name}");
        assert_eq!(found[0].confidence, confidence, "{region} {name}");
        assert_eq!(found[0].regions, [region], "{region} {name}");
        assert!(!found[0].source.is_empty(), "{region} {name}");
    }
}

#[test]
fn before_its_first_year_a_commemorative_day_is_absent_or_a_gap() {
    for &(region, name, first, established) in FIRST_YEARS {
        let before = first - 1;
        assert!(
            named(region, name, before).is_empty(),
            "{region} {name} {before}"
        );
        let gap = HolidayCalendar::for_year(&UNITED_STATES, Some(region), before)
            .gaps()
            .iter()
            .any(|gap| gap.name == name && gap.year == before);
        assert_eq!(gap, !established, "{region} {name} {before}");
    }
}

#[test]
fn a_commemorative_day_is_its_state_s_alone_and_closes_nothing() {
    for &(region, name, year, month, day, _) in ANCHORS {
        let date = ymd(year, month, day);
        assert!(
            HolidayCalendar::for_year(&UNITED_STATES, None, year)
                .on(date)
                .iter()
                .all(|holiday| holiday.name != name || holiday.regions.is_empty()),
            "{region} {name}"
        );
        let calendar = HolidayCalendar::for_year(&UNITED_STATES, Some(region), year);
        assert!(
            calendar
                .on(date)
                .iter()
                .filter(|holiday| holiday.name == name)
                .all(|holiday| !holiday.is_day_off()),
            "{region} {name}"
        );
    }
}
